def transform(grid):
    g = np.array(grid).copy()
    bg = background(g)
    partners = {frozenset((4, 7)), frozenset((1, 8))}
    H, W = g.shape
    for y in range(H):
        xs = [x for x in range(W) if g[y, x] != bg]
        for a, b in zip(xs, xs[1:]):
            if frozenset((int(g[y, a]), int(g[y, b]))) in partners and b > a + 1:
                c = g[y, b]
                g[y, b] = bg
                g[y, a + 1] = c
                emit(g, f"Row {y}: colour {c} is the partner of colour {g[y, a]}, so it slides left to sit next to it at x={a + 1}.")
    emit(g, "All partner pairs ({4,7} and {1,8}) are now adjacent; final grid.")
    return g
